try{var data=Newtonsoft.Json.Linq.JObject.Parse(System.IO.File.ReadAllText(@"C:\Users\Stormtrooper\Git\EVOLVE - Frame\output\revit\build_manifest.json"));var marks=new[]{"GF-SUITE-N","GF-BED-N","GF-BED-W","GF-WIR-W","GF-ENS-E","GF-ENS-W","GF-WC-N","GF-VD-W1","GF-VD-W2","GF-VD-S","GF-VD-N"};
using(var tx=new Transaction(document,"A07 ground suite dimension correction")){tx.Start();
 var old=new FilteredElementCollector(document).OfClass(typeof(Wall)).Cast<Wall>().Where(w=>marks.Contains(w.get_Parameter(BuiltInParameter.ALL_MODEL_MARK).AsString())).Select(w=>w.Id).ToList();foreach(var id in old)document.Delete(id);
 var level=new FilteredElementCollector(document).OfClass(typeof(Level)).Cast<Level>().Single(l=>l.Name.StartsWith("00 Ground FFL"));var type=new FilteredElementCollector(document).OfClass(typeof(WallType)).Cast<WallType>().Single(t=>t.Name.StartsWith("LC - 90mm"));
 foreach(var row in data["walls"].Where(r=>marks.Contains((string)r["mark"]))){var a=new XYZ((double)row["a"][0]/304.8,(double)row["a"][1]/304.8,0);var b=new XYZ((double)row["b"][0]/304.8,(double)row["b"][1]/304.8,0);var wall=Wall.Create(document,Line.CreateBound(a,b),type.Id,level.Id,2740/304.8,0,false,false);wall.get_Parameter(BuiltInParameter.ALL_MODEL_MARK).Set((string)row["mark"]);wall.get_Parameter(BuiltInParameter.ALL_MODEL_INSTANCE_COMMENTS).Set((string)row["source"]);document.Regenerate();bool h=Math.Abs(a.Y-b.Y)<1e-6;
 foreach(var o in row["openings"]){var c=(double)o["centre"]/304.8;var w=(double)o["width"]/609.6;var low=(double)o["sill"]/304.8;var high=low+(double)o["height"]/304.8;var op=document.Create.NewOpening(wall,h?new XYZ(c-w,a.Y,low):new XYZ(a.X,c-w,low),h?new XYZ(c+w,a.Y,high):new XYZ(a.X,c+w,high));op.get_Parameter(BuiltInParameter.ALL_MODEL_MARK)?.Set((string)o["mark"]);}
 }tx.Commit();}document.Save();return new{walls=new FilteredElementCollector(document).OfClass(typeof(Wall)).GetElementCount(),warnings=document.GetWarnings().Select(w=>w.GetDescriptionText()).ToArray()};}catch(Exception ex){return new{failure=ex.ToString()};}

